from math import isqrt

_RULE = {
    '.ab': '.', 'ab.': 'b', 'b..': 'a',
    '.ba': '.', 'ba.': 'a', 'a..': 'b',
    '..c': 'c', '.d.': 'd', 'a.c': 'd',
    'a.d': 'b', 'b.d': 'a', '.bd': 'c',
    'bd.': 'e', '.ad': 'c', 'ad.': 'e',
    'e..': 'd', 'd.c': 'c', '.dc': 'd',
    'dc.': 'a', '.da': 'd',
}
_FLIP = {'a': 'b', 'b': 'a', 'c': 'c', 'd': 'd', 'e': 'e'}


def _step(cells):
    candidates = set()
    for p in cells:
        candidates.update((p - 1, p, p + 1))
    get = cells.get
    out = {}
    for p in candidates:
        s = _RULE.get(get(p - 1, '.') + get(p, '.') + get(p + 1, '.'))
        if s and s != '.':
            out[p] = s
    return out


def _cavity(left, right, steps):
    # At the start of a lap: d at left, a at left+1, d at right.
    # A lap increases the width by one and lasts 2*width-2 steps.
    width = right - left
    b = 2 * width - 3
    laps = (isqrt(b * b + 4 * steps) - b) // 2
    steps -= laps * (laps + b)
    right += laps
    width += laps
    if steps <= width - 2:
        return {left: 'd', left + 1 + steps: 'b' if steps & 1 else 'a', right: 'd'}
    if steps == width - 1:
        return {left: 'd', right - 1: 'c', right: 'e'}
    return {left: 'd', left + 2 * width - 2 - steps: 'c', right + 1: 'd'}


def predict(start, steps):
    cells = dict(start)
    finished = {}
    while steps and cells:
        positions = sorted(cells)

        # These particles move outwards at the maximal propagation speed.
        # Nothing in the remaining world can ever reach them.
        while positions and cells[positions[0]] == 'c' and (
                len(positions) == 1 or positions[1] - positions[0] > 2):
            p = positions.pop(0)
            finished[p - steps] = cells.pop(p)
        while positions:
            p = positions[-1]
            if cells[p] not in 'ab':
                break
            size = 1
            if (len(positions) > 1 and p - positions[-2] == 1
                    and cells[positions[-2]] in 'ab'
                    and cells[positions[-2]] != cells[p]):
                size = 2
            if len(positions) > size and positions[-size] - positions[-size - 1] <= 2:
                break
            for _ in range(size):
                p = positions.pop()
                s = cells.pop(p)
                finished[p + steps] = _FLIP[s] if steps & 1 else s
        if not positions:
            break
        if len(positions) == 1:
            p = positions[0]
            s = cells[p]
            if s == 'e':
                cells = {p + 1: 'd'}
            # a,b,c have already been removed above, so only d or e remains.
            break
        if (len(positions) == 3 and cells[positions[0]] == 'd'
                and cells[positions[1]] == 'a' and cells[positions[2]] == 'd'
                and positions[1] == positions[0] + 1
                and positions[2] - positions[0] >= 3):
            cells = _cavity(positions[0], positions[2], steps)
            break

        groups = []
        group = []
        for p in positions:
            if group and p - group[-1] > 2:
                groups.append(group)
                group = []
            group.append(p)
        groups.append(group)
        speeds = []
        for group in groups:
            if len(group) == 1:
                s = cells[group[0]]
                if s in 'ab':
                    speeds.append(1)
                elif s == 'c':
                    speeds.append(-1)
                elif s == 'd':
                    speeds.append(0)
                else:
                    break
            elif (len(group) == 2 and group[1] - group[0] == 1
                  and cells[group[0]] + cells[group[1]] in ('ab', 'ba')):
                speeds.append(1)
            elif all(cells[p] == 'd' for p in group) and all(
                    group[i + 1] - group[i] == 2 for i in range(len(group) - 1)):
                speeds.append(0)
            else:
                break
        if len(speeds) != len(groups):
            cells = _step(cells)
            steps -= 1
            continue

        jump = steps
        for i in range(len(groups) - 1):
            closing = speeds[i] - speeds[i + 1]
            if closing > 0:
                distance = groups[i + 1][0] - groups[i][-1]
                jump = min(jump, (distance - 2 + closing - 1) // closing)
        new = {}
        for group, speed in zip(groups, speeds):
            for p in group:
                s = cells[p]
                new[p + speed * jump] = _FLIP[s] if speed == 1 and jump & 1 else s
        cells = new
        steps -= jump
    finished.update(cells)
    return finished

